def api(path: str, *, method: str | None = None, payload: dict | None = None,
        paginate: bool = False, mutation: bool = False,
        idempotent: bool = False, absolute: bool = False):
    """Call the REST API under ``repos/<slug>/`` (or an absolute *path*).

    Pagination is manual (``?per_page=100&page=N``) so nothing here depends on
    a modern ``gh``.  Returns parsed JSON (``None`` for an empty response).
    """
    full = path if absolute else f"repos/{repo_slug()}/{path}"

    def one(page_path: str):
        args = ["api", page_path]
        if method:
            args += ["-X", method]
        input_text = None
        if payload is not None:
            args += ["--input", "-"]
            input_text = json.dumps(payload)
        out = run_gh(args, input_text=input_text, mutation=mutation,
                     idempotent=idempotent)
        return json.loads(out) if out.strip() else None

    if not paginate:
        return one(full)

    sep = "&" if "?" in full else "?"
    rows: list = []
    page = 1
    while True:
        batch = one(f"{full}{sep}per_page={PAGE}&page={page}")
        if not batch:
            break
        rows.extend(batch)
        if len(batch) < PAGE:
            break
        page += 1
    return rows
def list_labels() -> list[str]:
    return [row["name"] for row in api("labels", paginate=True)]


def issue_view(number: int) -> dict:
    return api(f"issues/{number}")


def _has_blocker(number: int, blocker: int) -> bool:
    rows = api(f"issues/{number}/dependencies/blocked_by", paginate=True)
    return any(int(row.get("number", -1)) == blocker for row in rows or [])


def add_blocked_by(number: int, blocker: int) -> None:
    """Ensure issue *number* is blocked by *blocker*.

    The prerequisite edge is read before writing so a repeated command adopts
    it without another mutation.  A failed POST is ambiguous, so the edge is
    read again and adopted if GitHub committed it before reporting failure.
    """
    if _has_blocker(number, blocker):
        return
    blocker_id = int(issue_view(blocker)["id"])
    try:
        api(f"issues/{number}/dependencies/blocked_by", method="POST",
            payload={"issue_id": blocker_id}, mutation=True)
    except LayerError as exc:
        if _has_blocker(number, blocker):
            return
        raise exc


